import unittest
from candidate import total_match

class TestTotalMatch(unittest.TestCase):
    def test_both_empty_lists_returns_first(self):
        self.assertEqual(total_match([], []), [])

    def test_first_list_fewer_chars(self):
        result = total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project'])
        self.assertEqual(result, ['hi', 'admin'])

    def test_second_list_fewer_chars(self):
        result = total_match(['hi', 'admin'], ['hI', 'Hi'])
        self.assertEqual(result, ['hI', 'Hi'])

    def test_equal_chars_returns_first_list(self):
        result = total_match(['hi', 'admin'], ['hI', 'hi', 'hi'])
        self.assertEqual(result, ['hi', 'admin'])

    def test_single_char_vs_multiple_chars(self):
        result = total_match(['4'], ['1', '2', '3', '4', '5'])
        self.assertEqual(result, ['4'])

    def test_empty_first_list_vs_nonempty_second(self):
        result = total_match([], ['a', 'b'])
        self.assertEqual(result, [])

    def test_nonempty_first_list_vs_empty_second(self):
        result = total_match(['a', 'b'], [])
        self.assertEqual(result, [])

    def test_single_empty_string_each(self):
        result = total_match([''], [''])
        self.assertEqual(result, [''])

    def test_empty_string_vs_nonempty_string(self):
        result = total_match([''], ['hello'])
        self.assertEqual(result, [''])

    def test_nonempty_string_vs_empty_string(self):
        result = total_match(['hello'], [''])
        self.assertEqual(result, [''])

    def test_multiple_empty_strings(self):
        result = total_match(['', '', ''], ['a'])
        self.assertEqual(result, ['', '', ''])

    def test_unicode_strings(self):
        result = total_match(['é', 'ñ'], ['a', 'b', 'c'])
        self.assertEqual(result, ['é', 'ñ'])

    def test_strings_with_whitespace(self):
        result = total_match(['  ', '  '], ['a'])
        self.assertEqual(result, ['  ', '  '])

    def test_single_character_strings(self):
        result = total_match(['a'], ['b'])
        self.assertEqual(result, ['a'])

    def test_long_string_vs_many_short_strings(self):
        result = total_match(['a' * 10], ['a', 'a', 'a', 'a', 'a'])
        self.assertEqual(result, ['a' * 10])

    def test_many_short_strings_vs_long_string(self):
        result = total_match(['a', 'a', 'a', 'a', 'a'], ['a' * 10])
        self.assertEqual(result, ['a', 'a', 'a', 'a', 'a'])

    def test_returns_same_object_reference_first(self):
        lst1 = ['hi', 'admin']
        lst2 = ['hI', 'hi', 'hi']
        result = total_match(lst1, lst2)
        self.assertIs(result, lst1)

    def test_returns_same_object_reference_second(self):
        lst1 = ['hi', 'admin']
        lst2 = ['hI', 'Hi']
        result = total_match(lst1, lst2)
        self.assertIs(result, lst2)

    def test_none_in_list_treated_as_error(self):
        with self.assertRaises(TypeError):
            total_match([None], ['a'])

    def test_integer_in_list_treated_as_error(self):
        with self.assertRaises(TypeError):
            total_match([1, 2], ['a'])

    def test_single_element_both_lists_equal(self):
        result = total_match(['abc'], ['def'])
        self.assertEqual(result, ['abc'])

    def test_nested_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            total_match([['a']], ['b'])

    def test_none_as_argument(self):
        with self.assertRaises(TypeError):
            total_match(None, ['a'])

    def test_none_as_second_argument(self):
        with self.assertRaises(TypeError):
            total_match(['a'], None)

    def test_tuple_as_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            total_match(('a', 'b'), ['c'])

    def test_string_as_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            total_match('hello', ['a'])

    def test_zero_length_strings_vs_one_length(self):
        result = total_match([''], ['a', 'b', 'c', 'd'])
        self.assertEqual(result, [''])

    def test_all_six_examples_from_docstring(self):
        self.assertEqual(total_match([], []), [])
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hI', 'Hi'])
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'hi', 'hi']), ['hi', 'admin'])
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_very_long_strings(self):
        long1 = 'a' * 1000
        long2 = 'b' * 2000
        result = total_match([long1], [long2])
        self.assertEqual(result, [long1])

    def test_mixed_length_strings(self):
        result = total_match(['a', 'bb', 'ccc'], ['dddd', 'e'])
        self.assertEqual(result, ['a', 'bb', 'ccc'])

    def test_case_sensitivity_of_strings_does_not_matter(self):
        result = total_match(['ABC'], ['abc'])
        self.assertEqual(result, ['ABC'])


if __name__ == '__main__':
    unittest.main()
